def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_time, id, qty) - we'll use negated price for max heap
    sell_book = []  # list of (price, arrival_time, id, qty) - min heap
    order_info = {}  # track all orders: id -> {'type': 'limit'/'ioc'/'market', 'side': 'buy'/'sell', 'qty': qty, 'filled_qty': filled_qty, 'price': price}
    arrival_counter = 0

    def match_buy(buy_id, buy_price, buy_qty, is_ioc_or_market):
        nonlocal buy_qty, arrival_counter

        sell_book.sort(key=lambda x: (x[0], x[1]))  # sort by price, then arrival time

        i = 0
        while i < len(sell_book) and buy_qty > 0:
            sell_price, sell_arrival, sell_id, sell_qty = sell_book[i]

            if sell_price <= buy_price:
                trade_qty = min(buy_qty, sell_qty)
                trades.append([buy_id, sell_id, sell_price, trade_qty])

                buy_qty -= trade_qty
                order_info[sell_id]['filled_qty'] += trade_qty

                if trade_qty == sell_qty:
                    sell_book.pop(i)
                else:
                    sell_book[i] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)
                    i += 1
            else:
                break

        if buy_qty > 0 and not is_ioc_or_market:
            # Add remaining to buy book
            buy_book.append((buy_price, arrival_counter, buy_id, buy_qty))
            order_info[buy_id]['qty'] = buy_qty

    def match_sell(sell_id, sell_price, sell_qty, is_ioc_or_market):
        nonlocal sell_qty, arrival_counter

        buy_book.sort(key=lambda x: (-x[0], x[1]))  # sort by price desc, then arrival time

        i = 0
        while i < len(buy_book) and sell_qty > 0:
            buy_price, buy_arrival, buy_id, buy_qty = buy_book[i]

            if buy_price >= sell_price:
                trade_qty = min(sell_qty, buy_qty)
                trades.append([buy_id, sell_id, buy_price, trade_qty])

                sell_qty -= trade_qty
                order_info[buy_id]['filled_qty'] += trade_qty

                if trade_qty == buy_qty:
                    buy_book.pop(i)
                else:
                    buy_book[i] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)
                    i += 1
            else:
                break

        if sell_qty > 0 and not is_ioc_or_market:
            # Add remaining to sell book
            sell_book.append((sell_price, arrival_counter, sell_id, sell_qty))
            order_info[sell_id]['qty'] = sell_qty

    for order in orders:
        order_type = order[0]

        if order_type == 'limit':
            _, order_id, side, price, qty = order
            arrival_counter += 1
            order_info[order_id] = {'type': 'limit', 'side': side, 'qty': qty, 'filled_qty': 0, 'price': price}

            if side == 'buy':
                match_buy(order_id, price, qty, False)
            else:  # sell
                match_sell(order_id, price, qty, False)

        elif order_type == 'ioc':
            _, order_id, side, price, qty = order
            arrival_counter += 1
            order_info[order_id] = {'type': 'ioc', 'side': side, 'qty': qty, 'filled_qty': 0, 'price': price}

            if side == 'buy':
                match_buy(order_id, price, qty, True)
            else:  # sell
                match_sell(order_id, price, qty, True)

        elif order_type == 'market':
            _, order_id, side, qty = order
            arrival_counter += 1
            order_info[order_id] = {'type': 'market', 'side': side, 'qty': qty, 'filled_qty': 0, 'price': None}

            if side == 'buy':
                match_buy(order_id, float('inf'), qty, True)
            else:  # sell
                match_sell(order_id, float('-inf'), qty, True)

        elif order_type == 'cancel':
            _, order_id = order

            # Try to remove from buy book
            buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != order_id]

            # Try to remove from sell book
            sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != order_id]

    return trades

